type Card={id:number,title:string,family:string,image:string,excerpt:string,views:number,historical_views?:number|null,historical_start?:string|null,historical_end?:string|null,url:string,author:string,license:string,license_url:string,file_url:string,inventory_id?:string,test_only?:number,plus?:number,copies?:number,mean_price?:number|null,sales_count?:number};
